package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamChemOrgBank1 {
  private const val T = "ලෝහ විද්‍යාව, හයිඩ්‍රොකාබන, බහුඅවයවික හා කාර්මික රසායනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "කාබනික හා කාර්මික රසායනයට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ධාරා ඌෂ්මකය (Blast furnace) තුළ හෙමටයිට් (Fe₂O₃) ලෝපසෙන් යකඩ නිස්සාරණය කිරීමේදී ප්‍රධාන ඔක්සිහාරකය ලෙස ක්‍රියා කරන වායුව කුමක්ද?", "කාබන් මොනොක්සයිඩ් (CO)", "ඔක්සිජන් (O₂)", "හයිඩ්‍රජන් (H₂)", "නයිට්‍රජන් (N₂)", "කෝක් (C) උණුසුම් වාතයේ දැවී CO₂ සාදා එය CO බවට හැරේ; Fe₂O₃ + 3CO → 2Fe + 3CO₂."),
    q("යකඩ නිස්සාරණයේදී ධාරා ඌෂ්මකයට හුණුගල් (CaCO₃) එකතු කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "පස් හා වැලි (SiO₂) අපද්‍රව්‍ය ඉවත් කර ලෝහ බොර (Slag) සෑදීම", "යකඩවල වර්ණය වෙනස් කිරීම", "උෂ්ණත්වය අඩු කිරීම", "ඔක්සිජන් සැපයීම", "CaO + SiO₂ → CaSiO₃ (ද්‍රව කැල්සියම් සිලිකේට්) ලෝහ බොර ලෙස පාවෙයි."),
    q("බොක්සයිට් (Al₂O₃·xH₂O) ලෝපසෙන් ඇලුමිනියම් නිස්සාරණය කරන විද්‍යුත් විච්ඡේදන ක්‍රියාවලියේදී ඇලුමිනා සමඟ ක්‍රයෝලයිට් (Na₃AlF₆) මිශ්‍ර කරන්නේ ඇයි?", "ඇලුමිනාවල ඉහළ ද්‍රවාංකය (2050°C) 950°C පමණ දක්වා අඩු කිරීමට", "ඇලුමිනියම්වල බර වැඩි කිරීමට", "ඔක්සිජන් පිටවීම නැවැත්වීමට", "විදුලිය විසන්ධි කිරීමට", "ක්‍රයෝලයිට් විද්‍යුත් සන්නායකතාව ද වැඩි කර බලශක්තිය ඉතිරි කරයි."),
    q("ඇලුමිනියම් නිස්සාරණය කරන විද්‍යුත් විච්ඡේදක කෝෂයේ කාබන් ඇනෝඩ කාලයත් සමඟ ක්ෂය වී නිතර අලුත් කිරීමට සිදු වන්නේ ඇයි?", "ඇනෝඩයේදී නිපදවෙන ඔක්සිජන් ඉහළ උෂ්ණත්වයේදී කාබන් සමඟ දැවී CO₂ සෑදීම", "ඇනෝඩ දියවීම", "ඇලුමිනියම් ඇනෝඩයේ තැන්පත් වීම", "ක්‍රයෝලයිට් ඇනෝඩ කෑම", "C(s) + O₂(g) → CO₂(g)."),
    q("ශ්‍රී ලංකාවේ පුල්මුඩේ වෙරළ තීරයේ බහුලව හමුවන ඉල්මනයිට් (FeTiO₃) හා රූටයිල් යන ඛනිජ වැලිවලින් නිස්සාරණය කරන වටිනා ලෝහය කුමක්ද?", "ටයිටේනියම් (Ti)", "රත්රන් (Au)", "ඇලුමිනියම් (Al)", "මැග්නීසියම් (Mg)", "ටයිටේනියම් සැහැල්ලු, ශක්තිමත් හා මලකඩ නොකන ලෝහයකි."),
    q("ශ්‍රී ලංකාවේ එප්පාවල ප්‍රදේශයේ පවතින ඇපටයිට් (Apatite) නිධිය කුමන කර්මාන්තයක් සඳහා ප්‍රධාන අමුද්‍රව්‍යයක් වේද?", "පොස්පේට් රසායනික පොහොර නිෂ්පාදනය", "සිමෙන්ති නිෂ්පාදනය", "වීදුරු නිෂ්පාදනය", "යකඩ නිස්සාරණය", "එප්පාවල පාෂාණ පොස්පේට් කෘෂිකර්මාන්තයේ පොස්පරස් පොහොර සඳහා වැදගත් වේ."),
    q("ශ්‍රී ලංකාවේ සේරුවිල ප්‍රදේශයේ පිහිටි ප්‍රධාන ලෝහ නිධියෙන් හමු වන්නේ කුමන ලෝහ ඛනිජයද?", "තඹ සහ මැග්නටයිට් (යකඩ)", "බොක්සයිට්", "රසදිය", "රන් පමණක්", "සේරුවිල තඹ-මැග්නටයිට් නිධිය ශ්‍රී ලංකාවේ ප්‍රධාන ඛනිජ සම්පතකි."),
    q("පිත්තල (Brass) මිශ්‍ර ලෝහය සෑදී ඇති ප්‍රධාන ලෝහ සංරචක දෙක මොනවාද?", "තඹ (Cu) සහ සින්ක් (Zn)", "තඹ සහ ටින්", "යකඩ සහ කාබන්", "ඊයම් සහ ටින්", "පිත්තල කපාට, සංගීත භාණ්ඩ හා සැරසිලි සඳහා භාවිත කෙරේ."),
    q("ලෝකඩ (Bronze) මිශ්‍ර ලෝහයේ ප්‍රධාන සංරචක මොනවාද?", "තඹ (Cu) සහ ටින් (Sn)", "තඹ සහ සින්ක්", "ඇලුමිනියම් සහ මැග්නීසියම්", "යකඩ සහ නිකල්", "පිළිම, පදක්කම් හා දුම්රිය රෝද බෙයාරිං සෑදීමට ලෝකඩ භාවිත කරයි."),
    q("විදුලි පරිපථ පෑස්සීම සඳහා භාවිත කරන අඩු ද්‍රවාංක මිශ්‍ර ලෝහය (Solder) සෑදී ඇත්තේ කුමන ලෝහවලින්ද?", "ඊයම් (Pb) සහ ටින් (Sn)", "තඹ සහ සින්ක්", "යකඩ සහ ක්‍රෝමියම්", "ඇලුමිනියම් සහ තඹ", "මෙම මිශ්‍ර ලෝහයේ ද්‍රවාංකය සංශුද්ධ ඊයම් හා ටින්වලට වඩා අඩුය."),
    q("මල නොබැඳෙන වානේ (Stainless steel) සෑදීමේදී යකඩ හා කාබන් සමඟ මිශ්‍ර කරන ප්‍රධාන ලෝහ මොනවාද?", "ක්‍රෝමියම් (Cr) සහ නිකල් (Ni)", "ඊයම් සහ ටින්", "සෝඩියම් සහ කැල්සියම්", "රසදිය සහ රිදී", "ශල්‍ය උපකරණ හා කුස්සියේ බඳුන් මලකඩ නොකා පවතින්නේ ක්‍රෝමියම් නිසාය."),
    q("ගුවන් යානා බඳ හා අභ්‍යවකාශ උපාංග නිපදවීමට ගන්නා 'ඩියුරැලුමින්' (Duralumin) මිශ්‍ර ලෝහයේ ප්‍රධාන ලෝහය කුමක්ද?", "ඇලුමිනියම් (Al)", "ඊයම් (Pb)", "යකඩ (Fe)", "රන් (Au)", "ඇලුමිනියම් සමඟ Cu, Mg හා Mn සුළු ප්‍රමාණ එක් කිරීමෙන් සැහැල්ලු නමුත් ඉතා ශක්තිමත් මිශ්‍ර ලෝහයක් ලැබේ."),
    q("සංශුද්ධ ලෝහවලට වඩා මිශ්‍ර ලෝහ (Alloys) වඩා දැඩි හා ශක්තිමත් වන්නේ ඇයි?", "වෙනස් ප්‍රමාණයේ පරමාණු ඇතුළත් වීමෙන් පරමාණු ස්තර ලිස්සා යාම අවහිර වීම", "මිශ්‍ර ලෝහවල අයනික බන්ධන සෑදීම", "ඝනත්වය ශුන්‍ය වීම", "විද්‍යුත් ප්‍රතිරෝධය ශුන්‍ය වීම", "විවිධ අරයන් ඇති පරමාණු දැලිසේ ක්‍රමවත් බව බිඳ දමයි."),
    q("කාබන් සහ හයිඩ්‍රජන් පමණක් අඩංගු කාබනික සංයෝග කාණ්ඩය හඳුන්වන්නේ කුමන නමින්ද?", "හයිඩ්‍රොකාබන", "ඇල්කොහොල", "කාබොක්සිලික් අම්ල", "එස්ටර", "ඛනිජ තෙල් හා ස්වාභාවික වායු ප්‍රධාන වශයෙන් හයිඩ්‍රොකාබනවලින් සෑදී ඇත."),
    q("සංතෘප්ත හයිඩ්‍රොකාබන (කාබන් පරමාණු අතර ඒක බන්ධන පමණක් ඇති) වන ඇල්කේන ශ්‍රේණියේ පොදු අණුක සූත්‍රය කුමක්ද?", "CₙH₂ₙ₊₂", "CₙH₂ₙ", "CₙH₂ₙ₋₂", "CₙHₙ", "n = 1 විට CH₄ (මීතේන්), n = 2 විට C₂H₆ (ඊතේන්) ලැබේ."),
    q("C₃H₈ යන අණුක සූත්‍රය හිමි ඇල්කේනය හඳුන්වන IUPAC නාමය කුමක්ද?", "ප්‍රොපේන් (Propane)", "මීතේන්", "ඊතේන්", "බියුටේන්", "කාබන් 3 ක් ඇති ඇල්කේනය ප්‍රොපේන් වේ."),
    q("LP ගෑස් සිලින්ඩරවල ප්‍රධාන වශයෙන් අධි පීඩනය යටතේ ද්‍රව කර අසුරා ඇති හයිඩ්‍රොකාබන මොනවාද?", "ප්‍රොපේන් (C₃H₈) සහ බියුටේන් (C₄H₁₀)", "මීතේන් පමණක්", "එතීන් සහ ඉතයින්", "ඔක්ටේන් පමණක්", "LP ගෑස්වල කාන්දුවක් හඳුනා ගැනීමට ගඳැති සල්ෆර් සංයෝග (Mercaptans) සුළු ප්‍රමාණයක් එක් කෙරේ."),
    q("එක් කාබන්-කාබන් ද්විත්ව බන්ධනයක් (C=C) අඩංගු අසංතෘප්ත හයිඩ්‍රොකාබන ශ්‍රේණිය හඳුන්වන්නේ කෙසේද?", "ඇල්කීන (Alkenes)", "ඇල්කේන", "ඇල්කයින", "ඇල්කොහොල", "ඇල්කීනවල පොදු සූත්‍රය CₙH₂ₙ වේ."),
    q("ඇල්කීන ශ්‍රේණියේ සරලතම සාමාජිකයා වන එතීන් (එතිලීන්) හි අණුක සූත්‍රය කුමක්ද?", "C₂H₄", "CH₄", "C₂H₆", "C₂H₂", "කාබන් පරමාණු දෙකක් අතර ද්විත්ව බන්ධනයක් ඇති බැවින් අවම කාබන් 2 ක් අවශ්‍ය වේ."),
    q("සංතෘප්ත ඇල්කේනයක් සහ අසංතෘප්ත ඇල්කීනයක් රසායනාගාරයේදී වෙන් කර හඳුනා ගැනීමට බ්‍රෝමීන් ජලය යෙදූ විට කුමක් සිදුවේද?", "ඇල්කීනය මගින් රතු-දුඹුරු බ්‍රෝමීන් ජලය ඉක්මනින් අවර්ණ කරයි", "ඇල්කේනය පමණක් බ්‍රෝමීන් අවර්ණ කරයි", "දෙකම නිල් පැහැ වේ", "කිසිදු වෙනසක් නොවේ", "ඇල්කීනයේ C=C ද්විත්ව බන්ධනය හරහා බ්‍රෝමීන් ආකලන ප්‍රතික්‍රියාවක් සිදු කරයි."),
    q("හිරු එළිය (UV කිරණ) හමුවේ මීතේන් (CH₄) ක්ලෝරීන් සමඟ සිදු කරන ආදේශ ප්‍රතික්‍රියාවේ පළමු පියවරේදී සෑදෙන ප්‍රධාන කාබනික ඵලය කුමක්ද?", "ක්ලෝරෝමීතේන් (CH₃Cl)", "මෙතනෝල්", "එතීන්", "කාබන් මොනොක්සයිඩ්", "CH₄ + Cl₂ → CH₃Cl + HCl."),
    q("පොලිතීන් (Polythene) නිපදවීමේදී ඒකාවයවිකය (Monomer) ලෙස යොදා ගන්නා වායුමය හයිඩ්‍රොකාබනය කුමක්ද?", "එතීන් (CH₂=CH₂)", "මීතේන් (CH₄)", "ඊතේන් (C₂H₆)", "ප්‍රොපේන් (C₃H₈)", "එතීන් අණු දහස් ගණනක් ආකලන බහුඅවයවීකරණයෙන් පොලිඑතීන් සාදයි."),
    q("ජල නල හා විදුලි කම්බි ආවරණ සෑදීමට ගන්නා PVC (පොලිවයිනයිල් ක්ලෝරයිඩ්) හි ඒකාවයවිකය කුමක්ද?", "වයිනයිල් ක්ලෝරයිඩ් / ක්ලෝරෝඑතීන් (CH₂=CHCl)", "එතීන්", "ටෙට්‍රාෆ්ලුවොරෝඑතීන්", "ස්ටයිරීන්", "PVC තාප සුවිකාර්‍ය ප්ලාස්ටික් වර්ගයකි."),
    q("නොඇලෙන තාච්චි (Non-stick pans) ආලේපනය සඳහා භාවිත කරන ටෙෆ්ලෝන් (PTFE) බහුඅවයවිකයේ ඒකාවයවිකය කුමක්ද?", "ටෙට්‍රාෆ්ලුවොරෝඑතීන් (CF₂=CF₂)", "එතීන්", "ප්‍රොපීන්", "ක්ලෝරෝඑතීන්", "C-F බන්ධන අතිශයින්ම ශක්තිමත් බැවින් රසායනිකව නිෂ්ක්‍රීය හා තාපයට ඔරොත්තු දේ."),
    q("ස්වාභාවික රබර් ලබා ගන්නා හීවියා රබර් කිරිවල අඩංගු බහුඅවයවිකයේ ඒකාවයවිකය කුමක්ද?", "අයිසොප්‍රීන් (2-මෙතිල්-1,3-බියුටාඩයීන්)", "එතීන්", "ග්ලූකෝස්", "ඇමයිනෝ අම්ල", "ස්වාභාවික රබර් යනු සිස්-පොලිඅයිසොප්‍රීන් වේ."),
    q("රබර් කිරි කැටි ගැස්වීම සඳහා වතු ආශ්‍රිත කර්මාන්තශාලාවල භාවිත කරන අම්ලය කුමක්ද?", "ෆෝමික් අම්ලය හෝ ඇසිටික් අම්ලය", "සාන්ද්‍ර නයිට්‍රික් අම්ලය", "හයිඩ්‍රොක්ලෝරික් අම්ලය", "සෝඩියම් හයිඩ්‍රොක්සයිඩ්", "දුබල කාබනික අම්ල රබර් අංශු මත සෘණ ආරෝපණ උදාසීන කර කැටි ගස්වයි."),
    q("රබර්වල ප්‍රත්‍යාස්ථතාව, ශක්තිය හා තාපයට ඔරොත්තු දීමේ ගුණය වැඩි කිරීම සඳහා සල්ෆර් සමඟ රත් කිරීමේ ක්‍රියාවලිය කුමක්ද?", "වල්කනයිස් කිරීම (Vulcanization)", "පැස්ටරීකරණය", "ආසවනය", "විද්‍යුත් විච්ඡේදනය", "සල්ෆර් පරමාණු රබර් දාම අතර හරස් බන්ධන (Cross-links) සාදයි."),
    q("වරක් රත් කර හැඩගැස්වූ පසු නැවත උණු කර වෙනත් හැඩයකට පත් කළ නොහැකි ප්ලාස්ටික් වර්ගය කුමක්ද? (උදා: බේක්ලයිට්)", "තාප දෘඪ ප්ලාස්ටික් (Thermosetting plastics)", "තාප සුවිකාර්‍ය ප්ලාස්ටික් (Thermoplastics)", "සෙලියුලෝස්", "ඉටි", "විදුලි ප්ලග්, ස්විච් හා පෑන් මිටවල් සෑදීමට බේක්ලයිට් යොදා ගනී."),
    q("පිෂ්ටය හා සෙලියුලෝස් යන ස්වාභාවික බහුඅවයවික දෙකම සෑදී ඇත්තේ කුමන ඒකාවයවිකය බහුඅවයවීකරණය වීමෙන්ද?", "ග්ලූකෝස්", "ඇමයිනෝ අම්ල", "එතීන්", "මේද අම්ල", "පිෂ්ටය α-ග්ලූකෝස් වලින් ද සෙලියුලෝස් β-ග්ලූකෝස් වලින් ද සෑදේ."),
    q("ස්වාභාවික ප්‍රෝටීන (උදා: ලොම්, සිල්ක්, එන්සයිම) සෑදී ඇති මූලික ඒකාවයවික ඒකක මොනවාද?", "ඇමයිනෝ අම්ල", "ග්ලූකෝස්", "නියුක්ලියෝටයිඩ", "අයිසොප්‍රීන්", "ඇමයිනෝ අම්ල පෙප්ටයිඩ බන්ධන මගින් බැඳී පොලිපෙප්ටයිඩ දාම සාදයි."),
    q("පෙට්‍රල්, ඩීසල් වැනි දිගු හයිඩ්‍රොකාබන අණු තාපය හා උත්ප්‍රේරක හමුවේ කුඩා ප්‍රයෝජනවත් ඇල්කේන හා ඇල්කීන බවට කඩා වෙන් කිරීම කුමක්ද?", "බිඳහෙළීම (Cracking)", "භාගික ආසවනය", "බහුඅවයවීකරණය", "සබන් සෑදීම", "Cracking මගින් ඉහළ ඉල්ලුමක් ඇති පෙට්‍රල් හා ප්ලාස්ටික් සඳහා එතීන් නිපදවයි."),
    q("මධ්‍යසාර පැසීමෙන් එතනෝල් (C₂H₅OH) නිපදවීමේදී ඒකාවයවික සීනි (C₆H₁₂O₆) මත ක්‍රියා කරන ජීවී එන්සයිමය සපයන්නේ කුමක්ද?", "යීස්ට් (සයිමේස් එන්සයිමය)", "ලැක්ටොබැසිලස්", "ඇසිටොබැක්ටර්", "රයිසෝබියම්", "C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂."),
    q("සබන් නිෂ්පාදනයේදී (Saponification) ශාක තෙල් හෝ සත්ව මේද රත් කරනු ලබන්නේ කුමන ප්‍රබල ක්ෂාරය සමඟද?", "සෝඩියම් හයිඩ්‍රොක්සයිඩ් (NaOH) හෝ KOH", "සල්ෆියුරික් අම්ලය", "ඇමෝනියා", "කැල්සියම් ක්ලෝරයිඩ්", "මේද + NaOH → සබන් (මේද අම්ලවල Na ලවණය) + ග්ලිසරෝල්."),
    q("රෙදි සේදීමේදී කඨින ජලය සමඟ පවා පෙණ නංවමින් කාර්යක්ෂමව ක්‍රියා කරන කෘත්‍රිම පිරිසිදුකාරක කාරක මොනවාද?", "කෘත්‍රිම ඩිටර්ජන්ට් (සෝප්ලස් ඩිටර්ජන්ට්)", "සාමාන්‍ය රෙදි සබන්", "පොල් තෙල් පමණක්", "හුණු දියර", "ඩිටර්ජන්ට්වල කැල්සියම් හා මැග්නීසියම් ලවණ ජලයේ දියවන බැවින් මණ්ඩි නොසාදයි."),
    q("සාමාන්‍ය සබන් කඨින ජලයේදී පෙණ නොනගවා සුදු පැහැති අද්‍රාව්‍ය මණ්ඩි (Scum) සාදන්නේ ජලයේ ඇති කුමන අයන නිසාද?", "Ca²⁺ සහ Mg²⁺ අයන", "Na⁺ සහ K⁺ අයන", "Cl⁻ සහ NO₃⁻ අයන", "SO₄²⁻ අයන පමණි", "සබන් Ca²⁺/Mg²⁺ සමඟ අද්‍රාව්‍ය කැල්සියම්/මැග්නීසියම් ස්ටියරේට් අවක්ෂේප සාදයි."),
    q("පානීය ජලයේ 'තාවකාලික කඨිනත්වය' (Temporary hardness) ඇති වන්නේ ජලයේ කුමන ලවණ දිය වී ඇති විටද?", "Ca(HCO₃)₂ සහ Mg(HCO₃)₂", "CaSO₄ සහ MgCl₂", "NaCl සහ KCl", "Na₂CO₃", "තාවකාලික කඨිනත්වය ජලය උතුරුවා ඉවත් කළ හැක."),
    q("තාවකාලික කඨිනත්වය ඇති ජලය උණු කළ විට කේතලය අභ්‍යන්තරයේ තැන්පත් වන සුදු පැහැති 'කිතුල/කබොල' (Scale) කුමන රසායනික ද්‍රව්‍යයද?", "කැල්සියම් කාබනේට් (CaCO₃)", "සෝඩියම් ක්ලෝරයිඩ්", "සල්ෆර්", "සිලිකා", "Ca(HCO₃)₂(aq) → CaCO₃(s) + H₂O(l) + CO₂(g)."),
    q("උතුරුවා ඉවත් කළ නොහැකි ජලයේ 'ස්ථිර කඨිනත්වය' ඉවත් කිරීම සඳහා භාවිත කළ හැකි රසායනික ක්‍රමයක් කුමක්ද?", "රෙදි සෝදන සෝඩා (Na₂CO₃) එක් කිරීම හෝ අයන හුවමාරු රෙසින", "ජලය උතුරුවා පෙරීම", "ක්ලෝරීන් දැමීම", "සීනි දැමීම", "Na₂CO₃ මඟින් Ca²⁺ අයන අද්‍රාව්‍ය CaCO₃ ලෙස අවක්ෂේප කෙරේ."),
    q("සිමෙන්ති නිෂ්පාදනයේදී ක්ලින්කර් සමඟ ජිප්සම් (CaSO₄·2H₂O) කුඩා ප්‍රමාණයක් අඹරා මිශ්‍ර කරන්නේ ඇයි?", "ජලය මිශ්‍ර කළ විගස සිමෙන්ති ඉතා ඉක්මනින් සවි වීම පාලනය (ප්‍රමාද) කිරීමට", "සිමෙන්තිවල වර්ණය කළු කිරීමට", "සිමෙන්ති දියර කිරීමට", "මලකඩ නැති කිරීමට", "බදාමය ඇතිරීමට ප්‍රමාණවත් කාලයක් ලැබීමට ජිප්සම් අත්‍යවශ්‍ය වේ."),
    q("සිමෙන්ති නිෂ්පාදනයට භාවිත කරන ප්‍රධාන අමුද්‍රව්‍ය දෙක මොනවාද?", "හුණුගල් (CaCO₃) සහ මැටි (Clay)", "වැලි සහ ලුණු", "යකඩ සහ සල්ෆර්", "කොම්පෝස්ට් සහ වැලි", "හුණුගල් කැල්සියම් ඔක්සයිඩ් ද මැටි සිලිකා හා ඇලුමිනා ද සපයයි."),
    q("ශ්‍රී ලංකාවේ පුත්තලම හා හම්බන්තොට ලුණු ලේවායන්හි NaCl ස්ඵටික වෙන් කර ගැනීමෙන් පසු ඉතිරි වන තිත්ත රසැති 'මවු ද්‍රාවණයේ' (Bittern) ප්‍රධාන ලවණය කුමක්ද?", "මැග්නීසියම් ක්ලෝරයිඩ් (MgCl₂) හා MgSO₄", "සීනි", "කැල්සියම් කාබනේට්", "රන්", "මුහුදු ජලයේ ඇති CaSO₄ පළමුව ද NaCl දෙවනුව ද MgCl₂ අවසානයේ ද ස්ඵටික වේ."),
    q("කාබන් මොනොක්සයිඩ් (CO) වායුව හුස්ම ගැනීම අතිශයින් මාරාන්තික වන්නේ ඇයි?", "හිමොග්ලොබින් සමඟ ස්ථායී කාබොක්සිහිමොග්ලොබින් සාදා ඔක්සිජන් ප්‍රවාහනය නැවැත්වීම", "පෙනහලු පුළුස්සා දැමීම", "රුධිරය කැටි ගැස්වීම", "අස්ථි දිය කිරීම", "අසම්පූර්ණ දහනයේදී (වාතය මද විට) CO වායුව නිපදවේ."),
    q("ෆොසිල ඉන්ධනයක් වන පෙට්‍රල් අඩංගු හයිඩ්‍රොකාබනවල ප්‍රමිතිය හෙවත් දහන ගුණාත්මක බව මනින දර්ශකය කුමක්ද?", "ඔක්ටේන් අංකය (Octane number)", "pH අගය", "සීටේන් අංකය", "BOD අගය", "ඔක්ටේන් අංකය වැඩි වන තරමට එන්ජිමේ 'ගැස්සීම' (Knocking) අඩු වේ."),
    q("නාගරික ප්‍රදේශවල වාහන දුමෙන් පිටවන කළු දුමේ (අසම්පූර්ණ දහනය) අඩංගු ඝන අංශු මොනවාද?", "දැලි / කාබන් අංශු", "ඔක්සිජන්", "නයිට්‍රජන්", "ජල වාෂ්ප", "ඩීසල් එන්ජින් නිසි ලෙස සුසර නොකළ විට කාබන් අංශු බහුලව පිටවේ."),
    q("ජෛව ඩීසල් (Biodiesel) හා එතනෝල් වැනි ජෛව ඉන්ධන ෆොසිල ඉන්ධනවලට වඩා පරිසර හිතකාමී යැයි සැලකෙන්නේ ඇයි?", "පුනර්ජනනීය වීම හා කාබන්-උදාසීන ලෙස ශුද්ධ CO₂ වැඩිවීම අඩු කිරීම", "කිසිසේත් CO₂ පිට නොකිරීම", "සල්ෆර් වැඩිපුර පිට කිරීම", "භූගත පතල්වලින් ගැනීම", "ශාක වැඩෙන විට උරාගත් CO₂ ප්‍රමාණයට ආසන්න ප්‍රමාණයක් දහනයේදී නැවත මුදා හරී."),
    q("වීදුරු සෑදීමේදී ප්‍රධාන වශයෙන්ම භාවිත කරන සිලිකන් සංයෝගය කුමක්ද?", "සිලිකන් ඩයොක්සයිඩ් (SiO₂ - පිරිසිදු සිලිකා වැලි)", "සිලිකන් කාබයිඩ්", "සෝඩියම් ක්ලෝරයිඩ්", "මැග්නීසියම් ඔක්සයිඩ්", "සිලිකා වැලි, සෝඩා අළු (Na₂CO₃) හා හුණුගල් උණු කර වීදුරු සාදයි."),
    q("මිශ්‍ර ලෝහයක් වන ටයිටේනියම් හා යකඩ මෙන් නොව සංශුද්ධ රත්රන් (කැරට් 24) මෘදු බැවින් ආභරණ සෑදීමේදී ඊට තඹ හෝ රිදී මිශ්‍ර කරන්නේ ඇයි?", "රන්වල දැඩි බව හා ශක්තිය වැඩි කිරීමට", "රන්වල බර වැඩි කිරීමට", "රන් ජලයේ දිය කිරීමට", "රන් මලකඩ කෑමට", "කැරට් 22 යනු රන් කොටස් 22 කට වෙනත් ලෝහ කොටස් 2 ක් මිශ්‍ර කළ මිශ්‍ර ලෝහයකි."),
    q("මෙතේන්, එතේන් හා ප්‍රොපේන් යන හයිඩ්‍රොකාබන තුනම එකම 'සමජාතීය ශ්‍රේණියකට' (Homologous series) අයත් වන අතර යාබද සාමාජිකයන් දෙදෙනෙකු අතර ඇති සූත්‍ර වෙනස කුමක්ද?", "-CH₂- ඒකකයක වෙනස", "-H₂O- ඒකකයක වෙනස", "-CO₂- ඒකකයක වෙනස", "-OH- ඒකකයක වෙනස", "සෑම යාබද සාමාජිකයන් දෙදෙනෙකු අතරම සාපේක්ෂ අණුක ස්කන්ධයේ වෙනස 14 කි."),
    q("පොලිතීන් වර්ග අතරින් කිරි බෝතල්, ප්ලාස්ටික් බාල්දි හා පයිප්ප සෑදීමට ගන්නා ශක්තිමත් රේඛීය දාම සහිත පොලිතීන් වර්ගය කුමක්ද?", "HDPE (අධි ඝනත්ව පොලිඑතීන්)", "LDPE (අඩු ඝනත්ව පොලිඑතීන්)", "PVC", "PTFE", "LDPE අතු බෙදුණු දාම සහිත බැවින් සිහින් බෑග් සෑදීමට ගනී."),
    q("ස්ටයිරීන් (Phenylethene) ඒකාවයවිකය බහුඅවයවීකරණය වීමෙන් සෑදෙන කෘත්‍රිම බහුඅවයවිකය කුමක්ද?", "පොලිස්ටයිරීන් (Polystyrene)", "පොලිතීන්", "නයිලෝන්", "ටෙෆ්ලෝන්", "රෙජිෆෝම් ඇසුරුම් හා කේක් පෙට්ටි සෑදීමේදී පොලිස්ටයිරීන් භාවිත වේ."),
    q("කෘත්‍රිම රෙදිපිළි හා ප්ලාස්ටික් බීම බෝතල් (PET) නිපදවීමට ගන්නා PET බහුඅවයවිකයේ සම්පූර්ණ රසායනික නාමය කුමක්ද?", "පොලිඑතිලීන් ටෙරෙප්තලේට් (Polyethylene terephthalate)", "පොලිවයිනයිල් ක්ලෝරයිඩ්", "පොලිප්‍රොපිලීන්", "පොලිටෙට්‍රාෆ්ලුවොරෝඑතීන්", "PET යනු පහසුවෙන් ප්‍රතිචක්‍රීකරණය කළ හැකි පොලියෙස්ටර් වර්ගයකි."),
    q("සබන් හා ග්ලිසරෝල් නිපදවන Saponification ප්‍රතික්‍රියාවේදී ශාක තෙල්වල පවතින මේද අම්ලවල කාබන් සංඛ්‍යාව සාමාන්‍යයෙන් කෙබඳුද?", "කාබන් 12–18 පමණ දිගු දාම", "කාබන් 1–2 කෙටි දාම", "කාබන් නොමැත", "කාබන් 1000 ක් පමණ", "සෝඩියම් ස්ටියරේට් (C₁₇H₃₅COONa) හා සෝඩියම් පාමිටේට් සබන්වල බහුලය."),
    q("අපිරිසිදු ඊයම්, තඹ හා ඇලුමිනියම් වැනි ලෝහ අතරින් ඉතා අඩු උෂ්ණත්වයකදී (660°C) උණු වී, කේබල් සඳහා ගන්නා සැහැල්ලු ලෝහය කුමක්ද?", "ඇලුමිනියම් (Al)", "යකඩ (1538°C)", "තඹ (1085°C)", "ටංස්ටන් (3422°C)", "ඇලුමිනියම්වල ඝනත්වය 2.7 g cm⁻³ පමණ වන අතර යකඩ 7.9 g cm⁻³ වේ."),
    q("යකඩ නිස්සාරණයේදී ධාරා ඌෂ්මකයේ ඉහළ උෂ්ණත්ව කලාපයේදී සෑදෙන කාබන් ඩයොක්සයිඩ් (CO₂) තවත් රත් වූ කෝක් (C) සමඟ ප්‍රතික්‍රියා කර සාදන වායුව කුමක්ද?", "කාබන් මොනොක්සයිඩ් (CO)", "ඔක්සිජන් (O₂)", "මීතේන්", "හයිඩ්‍රජන්", "CO₂(g) + C(s) → 2CO(g)."),
    q("ඇලුමිනියම් නිස්සාරණයේදී (Hall-Héroult ක්‍රමය) බොක්සයිට් ලෝපස මුලින්ම NaOH සමඟ ප්‍රතික්‍රියා කර පිරිපහදු කිරීමේදී ඉවත් කෙරෙන ප්‍රධාන අපද්‍රව්‍යය කුමක්ද?", "යකඩ(III) ඔක්සයිඩ් හා වැලි (රතු මඩ / Red mud)", "කාබන්", "ක්‍රයෝලයිට්", "සෝඩියම් ක්ලෝරයිඩ්", "ඇලුමිනියම් ඔක්සයිඩ් උභයගුණී බැවින් NaOH වල දිය වී සෝඩියම් ඇලුමිනේට් සාදන අතර Fe₂O₃ නොදියවේ."),
    q("ශ්‍රී ලංකාවේ හුණුගල්, මැටි හා ඛනිජ වැලි අතරින් 'ඩොලමයිට්' (Dolomite) ඛනිජය රසායනිකව කුමන සංයෝගයද?", "කැල්සියම් මැග්නීසියම් කාබනේට් (CaCO₃·MgCO₃)", "කැල්සියම් සල්ෆේට්", "සෝඩියම් සිලිකේට්", "ඇලුමිනියම් ඔක්සයිඩ්", "ඩොලමයිට් පසේ මැග්නීසියම් ඌනතාව නැති කිරීමට හා ආම්ලිකතාව අඩු කිරීමට ගොවිතැනේදී යොදයි."),
    q("බොරතෙල් භාගික ආසවනයේදී ලැබෙන විවිධ භාග අතරින් 'පාරවල් තාර දැමීමට' ගන්නා භාගය හා 'බර වාහන/ලොරි ඉන්ධනය' පිළිවෙළින් මොනවාද?", "බිටුමන් සහ ඩීසල්", "පෙට්‍රල් සහ නැප්තා", "LP ගෑස් සහ භූමිතෙල්", "ලිහිසි තෙල් සහ පෙට්‍රල්", "ඩීසල් එන්ජින් ස්පාර්ක් ප්ලග් නොමැතිව සම්පීඩන ජ්වලනයෙන් ක්‍රියා කරයි."),
    q("කිසියම් හයිඩ්‍රොකාබන සංයෝගයක් කාමර උෂ්ණත්වයේදී රතු-දුඹුරු බ්‍රෝමීන් ජලය අවර්ණ කරන්නේ නම් එම සංයෝගයේ අනිවාර්යයෙන්ම පවතින්නේ කුමක්ද?", "කාබන්-කාබන් ද්විත්ව (C=C) හෝ ත්‍රිත්ව (C≡C) බන්ධනයක්", "ඒක බන්ධන පමණක්", "ක්ලෝරීන් පරමාණුවක්", "ඔක්සිජන් පරමාණුවක්", "බ්‍රෝමීන් ජල පරීක්ෂාව අසංතෘප්ත බව හඳුනා ගැනීමේ සම්මත පරීක්ෂණයකි."),
    q("ඇල්කේනයක් වන ඊතේන් (C₂H₆) හි කාබන් පරමාණු දෙක අතර ඇති සහසංයුජ බන්ධනය කෙබඳුද?", "තනි ඒක බන්ධනයක් (C-C)", "ද්විත්ව බන්ධනයක්", "ත්‍රිත්ව බන්ධනයක්", "අයනික බන්ධනයක්", "ඊතේන්හි සෑම කාබන් පරමාණුවක්ම තවත් බන්ධන 4 කින් වට වී ඇත."),
    q("එතීන් (C₂H₄) හා ක්ලෝරීන් (Cl₂) කාමර උෂ්ණත්වයේදී අඳුරේ පවා ආකලන ප්‍රතික්‍රියාවක් සිදු කළ විට සෑදෙන ඵලය කුමක්ද?", "1,2-ඩයික්ලෝරෝඊතේන් (CH₂Cl-CH₂Cl)", "ක්ලෝරෝමීතේන්", "HCl පමණක්", "කාබන් ටෙට්‍රාක්ලෝරයිඩ්", "ද්විත්ව බන්ධනය විවෘත වී Cl පරමාණු දෙක එකතු වේ."),
    q("කාබනික සංයෝග වන මීතේන්, එතීන් හා එතනෝල් අතුරින් ජලයේ ඕනෑම අනුපාතයකින් ඉතා හොඳින් දියවන්නේ කුමක්ද?", "එතනෝල් (C₂H₅OH)", "මීතේන්", "එතීන්", "කිසිවක් නැත", "එතනෝල්හි ඇති ධ්‍රැවීය -OH කාණ්ඩය ජලය සමඟ හයිඩ්‍රජන් බන්ධන සාදයි."),
    q("මත්පැන් හා ඖෂධ කර්මාන්තයේදී සුලබව යොදා ගන්නා එතනෝල් හා මාරාන්තික විෂ සහිත මෙතනෝල් අතර ඇති රසායනික සූත්‍ර වෙනස කුමක්ද?", "එතනෝල් C₂H₅OH; මෙතනෝල් CH₃OH", "එතනෝල් CH₃OH; මෙතනෝල් C₂H₅OH", "දෙකම එකම අණුවකි", "මෙතනෝල් ඇල්කේනයකි", "මෙතනෝල් සුළු ප්‍රමාණයක් පවා පානය කිරීමෙන් අන්ධභාවය හා මරණය සිදුවේ."),
    q("හීවියා රබර් වගාවෙන් ලබාගන්නා රබර් කිරිවලින් 'දුම් ගැසූ රබර් ෂීට්' (RSS) සෑදීමේදී රබර් ෂීට් දුම් කාමරයේ වියළන්නේ ඇයි?", "තෙතමනය ඉවත් කිරීමට හා දුමේ ඇති ප්‍රතිදිලීරක ද්‍රව්‍යවලින් පුස් බැඳීම වැළැක්වීමට", "රබර් දිය කිරීමට", "සල්ෆර් ඉවත් කිරීමට", "රබර් කුඩු කිරීමට", "ක්‍රියෝසෝට් වැනි දුම් සංඝටක රබර් කල් තබා ගනී."),
    q("බොහෝ මිශ්‍ර ලෝහ සෑදීමේදී තඹ හා සින්ක් වෙනුවට ඇලුමිනියම් හා මැග්නීසියම් යොදා ගන්නේ කුමන ක්ෂේත්‍රයේ භාවිත සඳහාද?", "ගුවන් යානා හා සැහැල්ලු වාහන කොටස් නිපදවීම", "බර නැව් නැංගුරම් සෑදීම", "විලායක කම්බි සෑදීම", "දන්ත පිරවුම් සෑදීම", "අඩු ඝනත්වය හා ඉහළ ශක්තිය ගුවන් යානාවල ඉන්ධන ඉතිරි කරයි."),
    q("කාර්මිකව නිපදවන පොහොර අතරින් ඉහළම නයිට්‍රජන් ප්‍රතිශතයක් (46% පමණ) අඩංගු වන්නේ කුමන ඝන පොහොර වර්ගයේද?", "යූරියා (CO(NH₂)₂)", "ඇමෝනියම් සල්ෆේට් ((NH₄)₂SO₄)", "සෝඩියම් නයිට්‍රේට්", "මියුරියේට් ඔෆ් පොටෑෂ්", "යූරියා ඇමෝනියා සහ CO₂ ප්‍රතික්‍රියාවෙන් නිපදවයි."),
    q("ශාක පොහොර ඇසුරුම්වල 'NPK 10:20:10' ලෙස සඳහන් කර ඇති අංකවලින් කියැවෙන්නේ කුමක්ද?", "නයිට්‍රජන්, පොස්පරස් සහ පොටෑසියම් අඩංගු ප්‍රතිශත අනුපාතය", "පොහොර මිල ගණන", "ජල ප්‍රතිශතය", "විකුණුම් දිනය", "පොස්පරස් මූල වර්ධනයට ද පොටෑසියම් මල් පල හටගැනීම හා රෝග ප්‍රතිරෝධයට ද උපකාරී වේ."),
    q("වෙරළාශ්‍රිත කර්මාන්තශාලාවලින් සිප්පි කටු හා හිරිගල් පිළිස්සීමෙන් නිපදවන 'පිළිස්සූ හුණු' රසායනිකව කුමක්ද?", "කැල්සියම් ඔක්සයිඩ් (CaO)", "කැල්සියම් හයිඩ්‍රොක්සයිඩ්", "කැල්සියම් කාබනේට්", "සෝඩියම් කාබනේට්", "කොරල්පර හා හිරිගල් කැඩීම පරිසර විනාශයට හේතු වන බැවින් නීතියෙන් තහනම් කර ඇත."),
    q("බොක්සයිට් ලෝපසෙන් ඇලුමිනියම් නිස්සාරණය කරන විද්‍යුත් විච්ඡේදක කෝෂයේ ධන හා සෘණ ඉලෙක්ට්‍රෝඩ දෙකම සාදා ඇත්තේ කුමන ද්‍රව්‍යයෙන්ද?", "මිනිරන් (ග්‍රැෆයිට් / කාබන්)", "තඹ", "සින්ක්", "ඊයම්", "ඇලුමිනියම් අයන කාබන් බඳුනේ කැතෝඩ ලයිනිමේදී ඔක්සිහරණය වී ද්‍රව ඇලුමිනියම් ලෙස පතුලේ රැඳේ."),
    q("රසායනික සූත්‍රය C₆H₆ වන, චක්‍රීය සැකැස්මක් ඇති ඇරොමැටික හයිඩ්‍රොකාබනය කුමක්ද?", "බෙන්සීන් (Benzene)", "හෙක්සේන්", "හෙක්සීන්", "සයික්ලොහෙක්සේන්", "බෙන්සීන් පිළිකා කාරක ද්‍රාවකයක් බැවින් පාසල් විද්‍යාගාරවල ආරක්ෂිතව භාවිත කෙරේ."),
    q("පෙට්‍රෝලියම් ඉන්ධනයක් වන 'ස්වාභාවික වායුව' (Natural gas) හි 85%–95% ක් පමණම අඩංගු ප්‍රධාන සංඝටකය කුමක්ද?", "මීතේන් (CH₄)", "බියුටේන්", "එතීන්", "හයිඩ්‍රජන්", "CNG (සම්පීඩිත ස්වාභාවික වායු) වාහන ඉන්ධනයක් ලෙස භාවිත වේ."),
    q("පොලිඑතිලීන්, පොලිප්‍රොපිලීන් සහ PVC යන ප්ලාස්ටික් තුනම සෑදෙන පොදු රසායනික ප්‍රතික්‍රියා ක්‍රමය කුමක්ද?", "ආකලන බහුඅවයවීකරණය (Addition polymerization)", "සංඝනීභවන බහුඅවයවීකරණය", "උදාසීනීකරණය", "වියෝජනය", "ද්විත්ව බන්ධන බිඳී කිසිදු අතුරු ඵලයක් පිට නොවී ඒකාවයවික එකිනෙක බැඳේ."),
    q("කිසියම් ලෝහමය නොවන මූලද්‍රව්‍යයක් වන සිලිකන් (Si) පෘථිවි කබොලේ බහුලවම ඇති මූලද්‍රව්‍ය අතර දෙවන ස්ථානය ගනී. ඉලෙක්ට්‍රොනික චිප හා සූර්ය කෝෂවලට එය යොදා ගන්නේ ඇයි?", "එය අර්ධ සන්නායක (Semiconductor) ගුණ පෙන්වීම", "එය ඉහළ සන්නායක ලෝහයක් වීම", "එය පූර්ණ පරිවාරකයක් වීම", "එය ජලයේ දියවීම", "සිලිකන් පවතින්නේ SiO₂ (වැලි/ක්වාට්ස්) ලෙසය."),
    q("කිසියම් රසායනික පොහොරක් වන 'සාමාන්‍ය සුපර් පොස්පේට්' (SSP) නිපදවීමට පාෂාණ පොස්පේට් සමඟ ප්‍රතික්‍රියා කරවන අම්ලය කුමක්ද?", "සල්ෆියුරික් අම්ලය (H₂SO₄)", "හයිඩ්‍රොක්ලෝරික් අම්ලය", "ඇසිටික් අම්ලය", "කාබනික් අම්ලය", "පාෂාණ පොස්පේට් ජලයේ දිය නොවන නිසා ශාකවලට උරාගත හැකි ද්‍රාව්‍ය පොස්පේට් බවට පත් කෙරේ."),
    q("සාමාන්‍යයෙන් ගිනි කූරු, රතිඤ්ඤා සහ සල්ෆියුරික් අම්ලය නිපදවීමේදී භාවිත කරන කහ පැහැති අලෝහ මූලද්‍රව්‍යය කුමක්ද?", "සල්ෆර් (S)", "පොස්පරස්", "ක්ලෝරීන්", "සෝඩියම්", "සල්ෆර් රබර් වල්කනයිස් කිරීමේදී ද අත්‍යවශ්‍ය වේ."),
    q("කැල්සියම් ක්ලෝරයිඩ් හා මැග්නීසියම් ක්ලෝරයිඩ් ලවණවලින් යුත් මුහුදු ජලයට වඩා ශ්‍රී ලංකාවේ වියළි කලාපයේ භූගත ළිං ජලයේ කඨිනත්වය වැඩි වීමට හේතුව කුමක්ද?", "පොළොව යට ඇති හුණුගල් (CaCO₃) හා ඩොලමයිට් පාෂාණ හරහා ජලය ගලා යෑමේදී Ca²⁺ හා Mg²⁺ දිය වීම", "වැසි ජලයේ ලුණු තිබීම", "ශාක මුල් Ca²⁺ පිට කිරීම", "වායුගෝලයේ Ca²⁺ තිබීම", "CO₂ දියවූ වැසි ජලය හුණුගල් දිය කර බයිකාබනේට් සාදයි."),
    q("කාබනික ද්‍රව්‍යයක් වන මීතේන් හා ක්ලෝරීන් අතර සිදුවන ආදේශ ප්‍රතික්‍රියාව අවසානයේදී සෑදෙන සියලු හයිඩ්‍රජන් පරමාණු විස්ථාපනය වූ සංයෝගය කුමක්ද?", "කාබන් ටෙට්‍රාක්ලෝරයිඩ් (CCl₄)", "ක්ලෝරෝමීතේන්", "ඩයික්ලෝරෝමීතේන්", "ක්ලෝරෝෆෝම් (CHCl₃)", "CH₄ → CH₃Cl → CH₂Cl₂ → CHCl₃ → CCl₄."),
    q("පැස්සීම් කටයුතු හා ලෝහ කැපීම්වලදී අධික තාපයක් ලබා ගැනීමට ඇසිටිලීන් (C₂H₂) වායුව දහනය කරන්නේ කුමන වායුව සමඟද?", "සංශුද්ධ ඔක්සිජන් (O₂)", "නයිට්‍රජන්", "කාබන් ඩයොක්සයිඩ්", "හීලියම්", "ඔක්සි-ඇසිටිලීන් දැල්ල වානේ පවා උණු කිරීමට සමත් වේ."),
    q("රෙදි සෝදන සබන් හා ෂැම්පූ නිෂ්පාදනයේදී සබන් සාදන තෙල්වලින් පොල් තෙල් වෙනුවට භාවිත කළ හැකි සත්ව හෝ ශාක තෙල් මොනවාද?", "පාම් තෙල්, ඔලිව් තෙල් හෝ සත්ව මේද (Tallow)", "ඛනිජ තෙල් (පැරෆින්)", "භූමිතෙල්", "ඩීසල්", "ඛනිජ තෙල් යනු හයිඩ්‍රොකාබන බැවින් ඒවායින් සබන් සෑදිය නොහැක."),
    q("කෘත්‍රිමව සාදන ලද සබන් කැටයක තෙල් සහ ජලය මිශ්‍ර කර සෙලවූ විට ජලය පිරිසිදු වී කුණු ඉවත් වන්නේ සබන් ජලයේ කුමන ගුණය අඩු කරන නිසාද?", "ජලයේ පෘෂ්ඨික ආතතිය අඩු කර තෙත් කිරීමේ හැකියාව වැඩි කිරීම", "ජලයේ තාපාංකය 0°C කිරීම", "ජලය ආම්ලික කිරීම", "ජලයේ ඝනත්වය 10 ගුණ කිරීම", "සබන් 'තෙත්කාරකයක්' (Surfactant) ලෙස ක්‍රියා කර තෙල් ජලයේ පයසීකරණය (Emulsify) කරයි."),
    q("යකඩ නිස්සාරණයේදී ධාරා ඌෂ්මකයේ පතුලේ එකතු වන ද්‍රව ලෝහ බොර (Slag) සහ ද්‍රව යකඩ වෙන් වී පවතින්නේ කුමන ආකාරයටද?", "ඝනත්වය අඩු ලෝහ බොර, ඝනත්වය වැඩි ද්‍රව යකඩ මත පාවෙයි", "යකඩ ඉහළින් පාවෙයි", "දෙකම සම්පූර්ණයෙන් මිශ්‍ර වේ", "බොර වාෂ්ප වී යයි", "උඩින් ඇති බොර තට්ටුව යකඩ වාතය සමඟ නැවත ඔක්සිකරණය වීම ද වළක්වයි."),
    q("කිසියම් ලෝහ පිළිම හා ඝණ්ඨාර තැනීමට තඹ සමඟ ටින් මිශ්‍ර කර සාදන ලෝකඩ මිශ්‍ර ලෝහයට වඩා 'නිකල්-ටයිටේනියම්' හෝ 'මල නොබැඳෙන වානේ' ශල්‍ය උපකරණවලට ගන්නේ ඇයි?", "මලකඩ නොකෑම, විෂබීජහරණයට ඔරොත්තු දීම හා ඉහළ දැඩි බව", "ඉතා මෘදු වීම", "ජලයේ දියවීම", "පහසුවෙන් නැමීම", "වානේවල ක්‍රෝමියම් ආරක්ෂිත ඔක්සයිඩ් පටලයක් සාදයි."),
    q("පෘථිවිය මත වායුගෝලීය උෂ්ණත්වය ඉහළ නැංවීමට දායක වන ෆොසිල ඉන්ධන දහනයේදී වැඩිපුරම පිටවන අපද්‍රව්‍ය වායුව කුමක්ද?", "කාබන් ඩයොක්සයිඩ් (CO₂)", "ඔක්සිජන් (O₂)", "හීලියම් (He)", "නියොන් (Ne)", "ගල් අඟුරු හා ඛනිජ තෙල් දහනය ප්‍රධාන මානව CO₂ ප්‍රභවයයි."),
    q("ලෝහ කර්මාන්තයේදී 'පිරිසිදු යකඩ' වෙනුවට ගොඩනැගිලි කම්බි හා පාලම් සඳහා 'මෘදු වානේ' (Mild steel) භාවිත කරන්නේ ඇයි?", "වානේ පිරිසිදු යකඩවලට වඩා බොහෝ ශක්තිමත් හා තද බවින් යුක්ත වීම", "පිරිසිදු යකඩ වායුවක් වීම", "වානේ කිසිදා බර නොවීම", "වානේ ඇලුමිනියම් වීම", "සුළු කාබන් ප්‍රමාණය (~0.25%) යකඩ පරමාණු ස්තර ලිස්සා යාම අවහිර කර ශක්තිය වැඩි කරයි."),
    q("C₂H₄, C₃H₆, C₄H₈ යන සංයෝග පෙළ සැලකීමේදී පෙනී යන්නේ කුමක්ද?", "සියල්ලම එක් ද්විත්ව බන්ධනයක් සහිත ඇල්කීන සමජාතීය ශ්‍රේණියට අයත් බව", "සියල්ල ඇල්කේන බව", "සියල්ල කාබනික අම්ල බව", "සියල්ල ඝන ද්‍රව්‍ය බව", "මේ සියල්ලම බ්‍රෝමීන් ජලය අවර්ණ කරයි."),
    q("ප්‍රොපේන් (C₃H₈) හා ඔක්සිජන් වායු මිශ්‍ර කර සම්පූර්ණයෙන් දහනය කළ විට එක් ප්‍රොපේන් මවුලයකින් නිපදවෙන H₂O මවුල ගණන කීයද?", "4 mol", "3 mol", "5 mol", "8 mol", "C₃H₈ + 5O₂ → 3CO₂ + 4H₂O."),
    q("රබර් ගසෙන් කිරි කැපීමෙන් පසු එම කිරිවල රබර් අංශු කැටි ගැස්වීමේදී යොදා ගන්නා ෆෝමික් අම්ලයේ (Formic acid) විද්‍යාත්මක නාමය කුමක්ද?", "මෙතනොයික් අම්ලය (HCOOH)", "එතනොයික් අම්ලය", "ප්‍රොපනොයික් අම්ලය", "සල්ෆියුරික් අම්ලය", "කුහුඹු විෂවල ද අඩංගු සරලම කාබොක්සිලික් අම්ලය මෙතනොයික් අම්ලයයි."),
    q("ජලයේ 'ස්ථිර කඨිනත්වය' ඇති කිරීමට ප්‍රධාන වශයෙන් හේතු වන ලවණ මොනවාද?", "කැල්සියම් සහ මැග්නීසියම් සල්ෆේට හා ක්ලෝරයිඩ (CaSO₄, MgSO₄, CaCl₂, MgCl₂)", "කැල්සියම් බයිකාබනේට් පමණක්", "සෝඩියම් ක්ලෝරයිඩ් පමණක්", "පොටෑසියම් නයිට්‍රේට්", "මේවා රත් කළ විට වියෝජනය වී අවක්ෂේප නොවන නිසා ස්ථිර කඨිනත්වය ලෙස හැඳින්වේ."),
    q("ගිනිගන්නාසුලු වායුවක් වන හයිඩ්‍රජන් කාර්මිකව විශාල වශයෙන් භාවිත වන ක්ෂේත්‍රයක් වන්නේ කුමක්ද?", "ඇමෝනියා නිෂ්පාදනය හා එළවළු තෙල් හයිඩ්‍රජනීකරණය (මාගරින් සෑදීම)", "වීදුරු සෑදීම", "සිමෙන්ති සෑදීම", "ලුණු නිස්සාරණය", "රොකට් ඉන්ධනයක් ලෙස ද ද්‍රව හයිඩ්‍රජන් භාවිත කෙරේ."),
    q("මූලද්‍රව්‍යයක් වන කාබන් හි බහුරූපී ආකාර අතුරින් 'වැඩි පෘෂ්ඨ වර්ගඵලයක් ඇති නිසා ජල පෙරහන්වල ගඳ හා වර්ණ ඉවත් කිරීමට' ගන්නා අසංවිධානාත්මක ආකාරය කුමක්ද?", "සක්‍රීය අඟුරු / දැව අඟුරු (Activated charcoal)", "දියමන්ති", "මිනිරන්", "සිලිකා", "සක්‍රීය අඟුරු කුඩා සිදුරු රැසක් සහිත බැවින් අපද්‍රව්‍ය අණු අධිශෝෂණය (Adsorb) කර ගනී."),
    q("වෙළඳපොළේ ඇති සීනි (සුක්‍රෝස් - C₁₂H₂₂O₁₁) හා සාමාන්‍ය ලුණු අතරින් ජලීය එතනෝල් නිපදවීමට පැසවීම සඳහා භාවිත කළ හැක්කේ කුමක්ද?", "සීනි (සුක්‍රෝස් / ග්ලූකෝස්)", "සෝඩියම් ක්ලෝරයිඩ්", "කැල්සියම් කාබනේට්", "වැලි", "යීස්ට්හි ඇති ඉන්වර්ටේස් හා සයිමේස් එන්සයිම සීනි එතනෝල් බවට පත් කරයි."),
    q("විදුලි හීටර් හා ඉස්තිරික්කවල තාපන දඟර සෑදීමට භාවිත කරන 'නික්‍රෝම්' මිශ්‍ර ලෝහයේ අඩංගු මූලද්‍රව්‍ය මොනවාද?", "නිකල් (Ni), ක්‍රෝමියම් (Cr) සහ යකඩ (Fe)", "ඊයම් සහ ටින්", "රන් සහ රිදී", "සෝඩියම් සහ කැල්සියම්", "නික්‍රෝම් ඉහළ ප්‍රතිරෝධයක් ඇති අතර රත් වූ විට මලකඩ නොකයි."),
    q("දී ඇති කාබනික සංයෝග අතුරින් එතනොයික් අම්ලය හඳුනා ගැනීමට බේකිං සෝඩා (NaHCO₃) එක් කළ විට දැකිය හැකි නිරීක්ෂණය කුමක්ද?", "බුබුළු දමමින් CO₂ වායුව පිට වීම", "රතු අවක්ෂේපයක් සෑදීම", "නිල් පැහැ වීම", "කිසිවක් නොවීම", "කාබොක්සිලික් අම්ල NaHCO₃ සමඟ CO₂ පිට කරන නමුත් ඇල්කොහොල (එතනෝල්) එසේ නොකරයි."),
    q("ශ්‍රී ලංකාවේ හමුවන මිනිරන් හා පොස්පේට් හැරුණු විට, මුහුදු වෙරළේ හමුවන සිලිකන් ඩයොක්සයිඩ් (SiO₂) බහුල සුදු ඛනිජ වැලි විශේෂය කුමක්ද?", "වීදුරු වැලි (Silica sand - නාත්තන්ඩිය/මාරවිල)", "ඉල්මනයිට්", "රූටයිල්", "මොනසයිට්", "නාත්තන්ඩිය හා අම්පාර ප්‍රදේශවල වීදුරු නිෂ්පාදනයට සුදුසු සිලිකා වැලි පවතී."),
    q("කිසියම් ප්ලාස්ටික් වර්ගයක් වන 'මෙලමයින්' (Melamine) කෑම පිඟන් හා කෝප්ප සෑදීමට ගන්නේ එහි කුමන ගුණය නිසාද?", "තාප දෘඪ (Thermosetting), දැඩි, නොබිඳෙනසුලු හා උණුසුම් ආහාරවලින් විකෘති නොවීම", "උණු වතුරේ දියවීම", "ඇදෙනසුලු බව", "ලෝහමය බව", "කෙසේ වෙතත් මෙලමයින් භාජන මයික්‍රොවේව් උඳුන්වල දැමීම සුදුසු නොවේ."),
    q("ලෝහ කැපුම් කර්මාන්තයේදී මෙන් ඉහළ තාපයට හා ඝර්ෂණයට ඔරොත්තු දීමට අඩු කාබන් වානේ හා මැංගනීස් වානේ සැසඳීමේදී, වානේවලට 'ටංස්ටන්' (W) එක් කිරීමෙන් ලැබෙන ගුණය කුමක්ද?", "අධික උෂ්ණත්වයේදී පවා දැඩි බව නොනැසී පැවතීම (වේගවත් කැපුම් යන්ත්‍ර තල සඳහා)", "වතුරේ පාවීම", "අඩු ද්‍රවාංකය", "මෘදු බව", "ටංස්ටන් වානේ (High-speed steel) ඩ්‍රිල් බිට් හා ලේත් තල සෑදීමට ගනී."),
    q("වීදුරුවල විනිවිදභාවය හා ශක්තිය වැඩි කිරීමට මෙන්ම පොසිල ඉන්ධන දහනයෙන් වාතයට එක්වන ඊයම් (Lead) දූෂණය නැවැත්වීමට වර්තමානයේ පෙට්‍රල්වලට එක් නොකරන ද්‍රව්‍යය කුමක්ද?", "ටෙට්‍රාඑතිල් ලෙඩ් (ඊයම් සංයෝග)", "එතනෝල්", "ඔක්ටේන්", "වාතය", "වර්තමානයේ පාවිච්චි කරන්නේ ඊයම් රහිත (Unleaded) පෙට්‍රල් වේ."),
    q("කිසියම් සාමාන්‍ය කාබනික ද්‍රව්‍යයක් වන 'ග්ලූකෝස්' (C₆H₁₂O₆) රසායනිකව හඳුන්වන්නේ කුමන කාබෝහයිඩ්‍රේට් කාණ්ඩය ලෙසද?", "මොනොසැකරයිඩයක් (ඒකසීනි)", "ඩයිසැකරයිඩයක්", "පොලිසැකරයිඩයක්", "ප්‍රෝටීනයක්", "ග්ලූකෝස් හා ෆ්රක්ටෝස් මොනොසැකරයිඩ ද, සුක්‍රෝස් ඩයිසැකරයිඩයක් ද, පිෂ්ටය පොලිසැකරයිඩයක් ද වේ.")
  )
}
